const blN=h=>{ui.blN=ui.blN||[];ui.blN.push(h)};
const blR=a=>a[Math.floor(Math.random()*a.length)],blG=()=>(Math.random()+Math.random()+Math.random()-1.5)/1.5,blC=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
function blS(){if(!S.bloom||typeof S.bloom!='object')S.bloom={seq:0,seasons:{},names:[]};const B=S.bloom;B.seasons=B.seasons||{};B.names=B.names||[];return B}
const blYear=d=>dayDate(d??S.day).getFullYear();
function blDates(Y){const a0=dateDay(new Date(Y,2,1)),a1=dateDay(new Date(Y,2,31)),apr=dateDay(new Date(Y,3,1));let e1=apr;while(dowOf(e1)!=0)e1++;const eps=[...Array(13)].map((_,i)=>e1+7*i);return{a0,a1,apr,eps,end:eps[12]}}
const blCur=()=>{const B=blS();return B.seasons[blYear()]||null};
const blSeason=y=>blS().seasons[y]||null;
const blDone=c=>c.out!=null;
// ---- contestant stats (company members read live; generated contestants are stored) ------------------------------------
function blM(c){return c.mid!=null?(get(c.mid)||(S.alumni||[]).find(m=>m.id==c.mid)||null):null}
const BL_OBJ=new WeakMap();
function blObj(c){const m=blM(c);if(m)return m;const n=c.n;if(!BL_OBJ.has(n))BL_OBJ.set(n,{id:n.id,name:n.name,stage:n.stage,hue:n.hue,ap:n.ap,pers:n.pers,age:n.age,pop:n.pop,fans:n.fans,nat:n.nat,status:'active',_bl:1});return BL_OBJ.get(n)}
function blSt(c){const m=blM(c);if(m){let w={ph:70,mh:70};try{w=wlOf(m)}catch(e){}return{vo:+m.sing||0,da:+m.dance||0,ra:Math.round(.55*(+m.sing||0)+.25*(+m.variety||0)+.2*(+m.cha||0)),ch:+m.cha||0,pa:+m.pas||0,po:+m.pop||0,mh:w.mh,ph:w.ph,pers:m.pers}}
 const n=c.n;return{vo:n.vo,da:n.da,ra:n.ra,ch:n.ch,pa:n.pa,po:n.po,mh:n.mh,ph:n.ph,pers:n.pers}}
const blName=c=>{const m=blM(c);return m?(m.stage||m.name):c.n.stage||c.n.name};
const blCo=c=>c.mid!=null?[S.co||'Your company',c.grp||'']:[c.n.co,c.n.grp];
// ---- applications --------------------------------------------------------------------------------------------------------
function blElig(m,Y){const D=blDates(Y),why=[];if(!m||m.status=='graduated')return{ok:false,why:[BL_T('Not an active member.','ไม่ใช่เมมเบอร์ที่ยังอยู่')]};
 if(m.grad)why.push(BL_T('Graduation has been announced.','ประกาศจบการศึกษาแล้ว'));let w=null;try{w=wlOf(m)}catch(e){}if(w&&w.leave)why.push(BL_T('On leave.','อยู่ระหว่างลาพัก'));
 if(m.bproj&&m.bproj.until>D.apr)why.push(BL_T(`Under a Project Group contract (${m.bproj.name}) until ${jd(m.bproj.until)}.`,`อยู่ในสัญญาวงโปรเจกต์ (${m.bproj.name}) ถึง ${jd(m.bproj.until)}`));
 let C=[];try{C=gsCommits(m.id,D.apr,D.end).filter(c=>c.src!='bloom'&&c.src!='th')}catch(e){}const seen=new Set();C.forEach(c=>{const k=(c.label||c.type)+'|'+c.day;if(seen.has(k)||seen.size>=4)return;seen.add(k);why.push(BL_T(`Scheduled: ${c.label||c.type} on ${jd(c.day)}.`,`มีตารางงาน: ${c.label||c.type} วันที่ ${jd(c.day)}`))});
 if(C.length>4)why.push(BL_T(`…and ${C.length-4} more commitment(s) between April 1 and EP.13.`,`…และอีก ${C.length-4} งานระหว่าง 1 เม.ย. ถึง EP.13`));return{ok:!why.length,why,conf:C.length}}
const BL_WHY=[['prove','I want to prove what I can do beyond my team.','อยากพิสูจน์ตัวเองให้มากกว่าในทีม'],['dance','I want to grow as a performer next to the best trainees.','อยากพัฒนาฝีมือการแสดงไปพร้อมกับเด็กฝึกเก่ง ๆ'],['fans','I want more people to know my name.','อยากให้คนรู้จักชื่อมากขึ้น'],['dream','Debuting through BLOOM has been my dream since I was little.','การเดบิวต์ผ่าน BLOOM คือความฝันตั้งแต่เด็ก'],['chance','I haven\'t had many chances yet. This could change everything.','ยังไม่ค่อยมีโอกาส รายการนี้อาจเปลี่ยนทุกอย่าง'],['vocal','I want the whole country to hear my voice.','อยากให้คนทั้งประเทศได้ยินเสียงของหนู'],['rival','A friend from another agency applied. I don\'t want to fall behind.','เพื่อนจากค่ายอื่นสมัครแล้ว ไม่อยากตามหลัง']];
function blWhy(m){const s=blSt({mid:m.id}),L=['prove','fans','rival','dream','dance','vocal'];if(s.po<40)L.push('chance','chance','fans');if(m.age<=18)L.push('dream','dream');if(s.vo>s.da+5)L.push('vocal','vocal');if(s.da>s.vo+5)L.push('dance','dance');return blR(L)}
function blApplyRoll(Z,first){const Y=Z.y;S.members.forEach(m=>{if(m.status=='graduated'||Z.apps[m.id])return;const E=blElig(m,Y);if(!E.ok)return;let w={mh:60};try{w=wlOf(m)}catch(e){}
  const p=blC((first?.06:.02)+(m.pas||50)/(first?600:1500)+(m.age<=21?.03:-.02)+((m.pop||0)<45?.04:0)+(w.mh<35?-.05:0),0,.4);if(Math.random()<p)Z.apps[m.id]={st:'applied',day:S.day,why:blWhy(m)}})}
function blApproved(Z){return Object.entries(Z.apps).filter(([id,a])=>a.st=='approved').map(([id])=>+id)}
function blAppSet(mid,st){const Z=blCur();if(!Z||Z.st!='apply')return toast(BL_T('Applications are only handled in March.','จัดการใบสมัครได้เฉพาะเดือนมีนาคม'),'err');const a=Z.apps[mid],m=get(mid);if(!a||!m)return toast(BL_T('She has not applied. Members decide for themselves whether to apply.','เธอยังไม่ได้สมัคร เมมเบอร์ตัดสินใจสมัครเอง'),'err');
 if(st=='approved'){const E=blElig(m,Z.y);if(!E.ok)return toast(BL_T('Not eligible: ','ไม่มีสิทธิ์: ')+E.why[0],'err');if(blApproved(Z).length>=BL_Q&&a.st!='approved')return toast(BL_T(`The company quota is full (${BL_Q} contestants).`,`โควตาของบริษัทเต็มแล้ว (${BL_Q} คน)`),'err')}
 if(!['approved','rejected','applied'].includes(st))return;a.st=st;a.dec=S.day;render()}
// ---- generated contestants ---------------------------------------------------------------------------------------------
function blNat(){let r=Math.random();for(const[n,w]of BL_NAT){r-=w;if(r<0)return n}return'JP'}
function blMkNpc(Z,i,used){const nat=blNat();const fnA=nat=='JP'?(Array.isArray(FN)?FN:FN.split(' ')):BL_FN[nat],lnA=nat=='JP'?(Array.isArray(LN)?LN:LN.split(' ')):BL_LN[nat];let name,t=0;do{name=nat=='KR'||nat=='CN'||nat=='TW'?blR(lnA)+' '+blR(fnA):blR(fnA)+' '+blR(lnA)}while(used.has(name)&&t++<200);used.add(name);
 const tal=Math.pow(Math.random(),.75),spec=Math.random(),ag=blR(BL_AG),base=34+tal*60,sd=()=>blG()*10;
 const vo=Math.round(blC(base+sd()+(spec<.35?12:spec>.7?-8:0),8,99)),da=Math.round(blC(base+sd()+(spec>.65?12:spec<.3?-8:0),8,99)),ra=Math.round(blC(base*.85+sd()+(Math.random()<.18?18:0),5,99));
 const deb=ag[1]&&Math.random()<.5,po=Math.round(blC((deb?30:8)+Math.pow(Math.random(),2.2)*(deb?65:40),1,99)),fans=Math.round(Math.pow(po/100,2.2)*120000+rnd(50,900));
 const stage=nat=='JP'?name.split(' ')[0]:name.split(' ').pop();
 return{id:9000000+Z.y%100*1000+i,name,stage,nat,age:rnd(14,24),hue:rnd(0,359),ap:rapp(),pers:blR(PERS),rar:tal>.85?'SR':tal>.6?'R':'N',vo,da,ra,ch:Math.round(blC(35+Math.random()*55)),pa:Math.round(blC(40+Math.random()*58)),po,fans,mh:rnd(45,95),ph:rnd(55,98),co:ag[0],grp:ag[1]}}
function blStart(Z){const D=blDates(Z.y),A=blApproved(Z).map(get).filter(Boolean),cs=[],used=new Set([...S.members.map(m=>m.name)]);
 A.forEach(m=>{const E=blElig(m,Z.y);if(!E.ok){Z.apps[m.id].st='withdrawn';Z.apps[m.id].wd=E.why[0];return}const g=grp(gsGid(m)),t=teamOf(m);cs.push({id:'c'+(cs.length+1),mid:m.id,grp:g?g.name:'',team:t?t.name:(m.status=='trainee'?TL():''),gid:g?g.id:null})});
 let i=0;while(cs.length<BL_N){const n=blMkNpc(Z,i++,used);cs.push({id:'c'+(cs.length+1),mid:null,n})}
 cs.forEach(c=>{c.sf=0;c.ep=[];c.sk={};c.vt={};c.rk={};c.ev=[]});Z.cs=cs;Z.st='air';Z.ep=0;Z.eps={};Z.theme={title:`${blR(BL_W1)} ${blR(BL_W2)}`};Z.started=S.day;
 blN(`<li>🌸 <b>${Z.name}</b> — ${BL_T(`filming starts. ${cs.filter(c=>c.mid!=null).length} of your members compete with ${cs.filter(c=>c.mid==null).length} trainees from other agencies. EP.01 airs ${jd(D.eps[0])}.`,`เริ่มถ่ายทำ เมมเบอร์ของคุณ ${cs.filter(c=>c.mid!=null).length} คน แข่งกับเด็กฝึกจากค่ายอื่น ${cs.filter(c=>c.mid==null).length} คน EP.01 ออกอากาศ ${jd(D.eps[0])}`)}</li>`)}
// ---- scoring helpers ------------------------------------------------------------------------------------------------------
const blAct=Z=>Z.cs.filter(c=>!blDone(c));
function blPerf(c,w){const s=blSt(c),k=w||{vo:.3,da:.3,ch:.2,pa:.2};let v=0,t=0;for(const x in k){v+=k[x]*(s[x]||0);t+=k[x]}v/=t||1;const sd=4+(100-s.mh)/14;return blC(v+blG()*sd*1.6+(s.ph<30?-4:0))}
const BL_A=80;function blGrade(sc){return sc>=BL_A?'A':sc>=66?'B':sc>=52?'C':sc>=40?'D':'F'}
// grades are given by placement: 12 trainees in each class (A, B, C, D, F)
function blGradeAll(L,sk,gk){const G=['A','B','C','D','F'],per=Math.ceil(L.length/5);L.slice().sort((a,b)=>b[sk]-a[sk]||Math.random()-.5).forEach((c,i)=>{c[gk]=G[Math.min(4,Math.floor(i/per))]})}
// scores are shown like every ability: out of 1,000
const blK=v=>Math.round(typeof skUnview=='function'?skUnview(v):(+v||0)*10);
const BL_GW={A:1,B:.8,C:.6,D:.45,F:.35};
function blExpose(c,x){c.sf=(c.sf||0)+Math.max(0,x)}
function blFanVotes(c){const m=blM(c);if(m){let k=0,o=0;try{const X=fbStats().M[m.id];if(X){k=X.k;o=X.o}}catch(e){}if(!k&&!o){k=(m.fans||0)*.4;o=(m.fans||0)*.3}return 260*Math.sqrt(k+.35*o)}return 260*Math.sqrt((c.n.fans||0)*.55)}
// the ranking is the vote count (as on real survival shows): votes come from existing fans, the exposure the trainee got on
// the show, how well she performed since the last ranking, and the support she already had (votes carry over in part)
function blRank(Z,epn){const A=blAct(Z),per=[3,6,9,12,13].filter(e=>e<epn).pop()||0,mis=A.map(c=>{const L=Object.entries(c.sk).filter(([e])=>+e>per&&+e<=epn).map(([,v])=>v);return L.length?avg(L):50});
 const pw=epn<=3?.8:epn<=9?1:1.15;
 A.forEach((c,i)=>{const fv=blFanVotes(c)*(epn>=9?.85:1),sv=c.sf*4.2,pv=70000*pw*Math.pow(mis[i]/100,2),prev=per?(c.vt[per]||0):0;c.vt[epn]=Math.round((fv+sv+pv)*(.93+Math.random()*.14)+prev*.3);c.ps=mis[i]});
 const mv=Math.max(...A.map(c=>c.vt[epn]))||1;A.forEach(c=>{c.rs=Math.round(c.vt[epn]/mv*1000)/10});
 const L=A.slice().sort((a,b)=>b.vt[epn]-a.vt[epn]);L.forEach((c,i)=>{c.rk[epn]=i+1});return L}
