function blEv(Z,epn,c,k,o,t){const T=BL_EV[k];if(!T)return;const nm=blName(c),on=o?blName(o):'',f=s=>s.replace('{n}',nm).replace('{o}',on).replace('{t}',t||'');const e={c:c.id,k,en:f(T[0]),th:f(T[1])};(Z.eps[epn].ev=Z.eps[epn].ev||[]).push(e);c.ev.push([epn,k]);return e}
function blEvents(Z,epn,ctx){const E=Z.eps[epn];E.ev=E.ev||[];const A=ctx.who||blAct(Z),pick=c=>c.mid!=null||Math.random()<.22;
 A.forEach(c=>{if(!pick(c))return;const s=blSt(c),r=ctx.res&&ctx.res[c.id],prev=ctx.prev&&ctx.prev[c.id];const opts=[];
  if(ctx.kind=='prac'){if(r!=null&&r>=70&&s.pa>60)opts.push('improve');if(r!=null&&r<45)opts.push('struggle');if(s.ch>70&&s.pa>65)opts.push('lead','centerfight');if(s.pa>70)opts.push('help');if(s.mh<45)opts.push('conflict');opts.push('friend')}
  else if(ctx.kind=='stage'){if(r!=null&&r>=78)opts.push('stand','praise');if(r!=null&&r<48)opts.push('mistake');if(r!=null&&r>=70&&(prev??60)<55)opts.push('recover','talent');if(r!=null&&r>=72&&s.po<35)opts.push('viral','attention')}
  else if(ctx.kind=='rank'){const rk=c.rk[epn];if(rk&&rk>BL_LEFT[epn]-6&&rk<=BL_LEFT[epn]+4)opts.push('anxiety');if(rk>BL_LEFT[epn]&&s.mh<55)opts.push('cry');if(rk&&c.rk[ctx.per]&&c.rk[ctx.per]-rk>=10)opts.push('attention')}
  if(!opts.length||Math.random()<.35)return;const k=blR(opts),o=['friend','help'].includes(k)?blR((ctx.team&&ctx.team[c.id])||A.filter(x=>x!==c)):null;if(o===c)return;blEv(Z,epn,c,k,o,ctx.tname&&ctx.tname[c.id]);
  const ex={improve:6,stand:10,praise:9,viral:14,attention:8,talent:9,recover:5,centerfight:4,lead:5,help:3,mistake:2,cry:4}[k]||1;blExpose(c,ex*60)})}
