V.blep=function(){const B=blS(),ys=Object.keys(B.seasons).map(Number).filter(y=>B.seasons[y].ep>0).sort((a,b)=>b-a);if(!ys.length)return`<div class="c"><p class="st">${BL_T('No episode has aired yet.','ยังไม่มีตอนที่ออกอากาศ')}</p></div>`;
 const Y=ys.includes(ui.blY)?ui.blY:ys[0],Z=B.seasons[Y],n=Math.min(Math.max(1,ui.blE||Z.ep),Z.ep),E=Z.eps[n],T=BL_EPS[n-1],mine=Z.cs.filter(c=>c.mid!=null),me=mine.filter(c=>E.st&&E.st[c.id]);
 let body='';const byId=id=>Z.cs.find(c=>c.id==id),row=(c,extra)=>`<div class="blrow ${c.mid!=null?'mine':''}">${ptc(blObj(c),36)}<b>${esc(blName(c))}</b><small>${esc(blCo(c)[0])}</small>${extra||''}</div>`;
 if(n==1||n==2){const k=n==1?'g1':'g2',sk=n==1?'s1':'s2';const G={A:[],B:[],C:[],D:[],F:[]};Z.cs.forEach(c=>G[c[k]]&&G[c[k]].push(c));body=`<h3>${BL_T('Grade results','ผลเกรด')}</h3>${Object.entries(G).map(([g,L])=>`<div class="blgsec"><div class="row">${blGB(g)}<b>${BL_T(...BL_GN[g])}</b><span class="st">${L.length}</span></div><div class="blrows">${L.sort((a,b)=>b[sk]-a[sk]).map(c=>row(c,`<span class="st">${blK(c[sk])}</span>${n==2&&c.g1?`<span class="st">${c.g1}→${c.g2}</span>`:''}${n==2&&c.cand?`<span class="tag tmain">${BL_T('Center candidate','ผู้มีสิทธิ์เป็นเซ็นเตอร์')}</span>`:''}${c.center&&n==2?`<span class="tag blctr">CENTER</span>`:''}`)).join('')}</div></div>`).join('')}
  ${n==2?`<div class="c blcen"><b>${BL_T('Theme Song Center','เซ็นเตอร์เพลงธีม')}: ${esc(blName(byId(Z.center)))}</b><p class="st">${BL_T(`Chosen among the ${Z.cands.length} Grade A trainee(s) of EP.02 by Theme Song performance, vocal, dance and stage presence.`,`เลือกจากผู้ได้เกรด A ใน EP.02 จำนวน ${Z.cands.length} คน โดยดูจากการแสดงเพลงธีม เสียงร้อง การเต้น และออร่าบนเวที`)}${E.sre&&E.sre.length?BL_T(' No trainee received Grade A at first: a special re-evaluation was held.',' ตอนแรกไม่มีใครได้เกรด A จึงมีการประเมินพิเศษ'):''}</p></div>`:''}`}
 if(E.rank){body=`<h3>${BL_T('Ranking','อันดับ')}</h3><div class="blrows">${E.rank.map(([id,r,v,ps,rs,pr])=>{const c=byId(id),mv=pr?pr-r:0;return row(c,`<span class="blrk2">#${r}</span><span class="st">${BL_T('Votes','โหวต')} ${v.toLocaleString()} · ${BL_T('Skill','ฝีมือ')} ${blK(ps)}</span>${pr?`<span class="blmv ${mv>0?'up':mv<0?'dn':''}">${mv>0?'▲'+mv:mv<0?'▼'+(-mv):'—'}</span>`:''}${c.out==n?`<span class="tag warn">${BL_T('Eliminated','ตกรอบ')}</span>`:n==13&&c.debut?`<span class="tag tmain">DEBUT</span>`:''}`)}).join('')}</div>${n==13?`<div class="c blcen"><b>${BL_T('Debut group','วงเดบิวต์')}: ${esc(Z.pg?Z.pg.name:'')}</b><p class="st">${BL_T(`${E.n} members debut.`,`เดบิวต์ ${E.n} คน`)}</p></div>`:''}`}
 if(E.teams&&(n==4||n==5||n==10||n==11)){const prep=Z.eps[n==5?4:n==11?10:n].teams;body=`<h3>${n==4||n==10?BL_T('Teams','ทีม'):BL_T('Results','ผลการแข่งขัน')}</h3><div class="blteams">${E.teams.map((t,i)=>{const P=prep[i];return`<div class="c blteam ${t.win?'win':''}"><div class="row"><b>${esc(t.name)}</b><span class="tag">${esc(t.concept||P.concept||'')}</span>${t.sc!=null?`<span class="tag ${t.win?'tmain':''}">${blK(t.sc)}${t.win?' · '+BL_T('WIN','ชนะ'):''}</span>`:''}</div><small>“${esc(t.song||P.song)}”${P.req?` · ${esc(BL_T(...P.req))}`:''}${P.days?` · ${P.days} ${BL_T('days of practice','วันซ้อม')}`:''}${P.prog!=null&&n==4?` · ${BL_T('practice','ความคืบหน้า')} ${P.prog}%`:''}${t.react?` · ${esc(t.react)}`:''}</small>
  <div class="blrows">${P.ids.map(id=>{const c=byId(id);return row(c,`<span class="st">${esc(P.pos[id]||'')}${P.center==id?' · Center':''}${P.parts?` · ${P.parts[id]}% ${BL_T('parts','ท่อนร้อง')}`:''}</span>${t.ind?`<span class="st">${blK(t.ind[id])}</span>`:''}${t.mvp==id?'<span class="tag tmain">MVP</span>':''}`)}).join('')}</div></div>`}).join('')}</div>`}
 if(n==7||n==8){const P=n==8?Z.eps[8].pos:null;body=`<h3>${BL_T('Positions','ตำแหน่ง')}</h3>${['Vocal','Dance','Rap'].map(p=>`<div class="blgsec"><b>${p}</b><div class="blrows">${(n==8?P[p]:Z.eps[7].pos[p].flatMap(t=>t.ids.map(id=>[id]))).map(([id,v],i)=>row(byId(id),n==8?`<span class="blrk2">${i+1}</span><span class="st">${blK(v)}</span>${i==0?`<span class="tag tmain">${BL_T('Position winner','ที่ 1 ตำแหน่ง')}</span>`:''}`:'')).join('')}</div></div>`).join('')}`}
 if(n==13&&E.iv)body=`<h3>${BL_T('Finalist interviews','สัมภาษณ์ผู้เข้ารอบชิง')}</h3><div class="blrows">${E.iv.map(id=>row(byId(id),`<span class="st">“${esc(blIv(Z,byId(id)))}”</span>`)).join('')}</div>`+body;
 const ev=(E.ev||[]).slice(0,40);
 return`<div class="c blep ${n==13?'finale':''}"><div class="row"><button class="b s" ${n<=1?'disabled':''} onclick="blOpenEp(${Y},${n-1})">◀ EP.${String(Math.max(1,n-1)).padStart(2,'0')}</button><select onchange="blOpenEp(${Y},+this.value)">${Object.keys(Z.eps).map(k=>`<option value="${k}" ${+k==n?'selected':''}>EP.${String(k).padStart(2,'0')}</option>`).join('')}</select><button class="b s" ${n>=Z.ep?'disabled':''} onclick="blOpenEp(${Y},${n+1})">EP.${String(Math.min(13,n+1)).padStart(2,'0')} ▶</button><span style="flex:1"></span><select onchange="ui.blY=+this.value;ui.blE=1;render()">${ys.map(y=>`<option ${y==Y?'selected':''}>${y}</option>`).join('')}</select></div>
 <div class="bleph"><span class="blepn">EP.${String(n).padStart(2,'0')}</span><div><b>${esc(BL_T(T[0],T[1]))}</b><small>${Z.name} · ${jd(E.day)}${E.left!=null?` · ${E.left} ${BL_T('contestants','คน')}`:''}</small></div></div><p class="st">${esc(BL_T(T[2],T[3]))}</p>
 ${me.length?`<h3>${BL_T('Your members this week','เมมเบอร์ของคุณในตอนนี้')}</h3><div class="blstills">${me.map(c=>`<figure>${blStillSvg(Z,n,c)}<figcaption><b>${esc(blName(c))}</b>${(c.ev||[]).filter(e=>e[0]==n).map(e=>{const x=(E.ev||[]).find(z=>z.c==c.id&&z.k==e[1]);return x?` · ${esc(BL_T(x.en,x.th))}`:''}).join('')}</figcaption></figure>`).join('')}</div>`:''}
 ${ev.length?`<h3>${BL_T('This week on BLOOM','ไฮไลต์ประจำสัปดาห์')}</h3><ul class="blev">${ev.map(e=>`<li>${esc(BL_T(e.en,e.th))}</li>`).join('')}</ul>`:''}${body}</div>`};
function blIv(Z,c){const s=blSt(c);return c.mid!=null||s.pa>70?BL_T('I came here to show who I really am. Tonight I\'ll give everything.','หนูมาที่นี่เพื่อแสดงตัวตนจริง คืนนี้จะทุ่มสุดตัว'):s.mh<50?BL_T('I was scared every week. I\'m still here — that already means a lot.','หนูกลัวทุกสัปดาห์ แต่ยังอยู่ตรงนี้ได้ แค่นั้นก็มีความหมายมากแล้ว'):BL_T('Whatever happens, I\'ll never forget these weeks.','ไม่ว่าผลจะเป็นยังไง จะไม่มีวันลืมช่วงเวลานี้')}
V.blcon=function(){const B=blS(),ys=Object.keys(B.seasons).map(Number).filter(y=>B.seasons[y].cs.length).sort((a,b)=>b-a);if(!ys.length)return`<div class="c"><p class="st">${BL_T('The roster is announced when filming starts on April 1.','ประกาศรายชื่อเมื่อเริ่มถ่ายทำ 1 เมษายน')}</p></div>`;const Y=ys.includes(ui.blY)?ui.blY:ys[0],Z=B.seasons[Y],F=ui.blcf||'all';
 const lastR=[13,12,9,6,3].find(e=>Z.eps[e]);let L=Z.cs.slice();if(F=='mine')L=L.filter(c=>c.mid!=null);if(F=='act')L=L.filter(c=>!blDone(c));L.sort((a,b)=>(lastR?(a.fin||a.rk[lastR]||a.outRk||99)-(b.fin||b.rk[lastR]||b.outRk||99):0)||(b.s2||b.s1||0)-(a.s2||a.s1||0));
 return`<div class="c"><div class="row"><select onchange="ui.blY=+this.value;render()">${ys.map(y=>`<option ${y==Y?'selected':''}>${y}</option>`).join('')}</select><b>${Z.name}</b>${['all','act','mine'].map(k=>`<button class="b s ${F==k?'on p':''}" onclick="ui.blcf='${k}';render()">${{all:BL_T('All 60','ทั้ง 60 คน'),act:BL_T('Remaining','ที่เหลือ'),mine:BL_T('Your members','เมมเบอร์ของคุณ')}[k]}</button>`).join('')}</div></div><div class="blgrid">${L.map(c=>blCard(Z,c,{rk:c.fin||(lastR?c.rk[lastR]:null),stats:1})).join('')}</div>`};
V.blpg=function(){const B=blS(),G=Object.values(B.seasons).filter(Z=>Z.pg).sort((a,b)=>b.y-a.y);return`<div class="c"><h3>${BL_T('Project Groups','วงโปรเจกต์')}</h3><p class="st">${BL_T('Debut groups of BLOOM: THE IDOL PROJECT. Each group is managed by the show\'s production company for two years — not by your company. A member of yours who debuts takes no part in her own group until the contract ends, then returns with many new fans.','วงเดบิวต์จาก BLOOM: THE IDOL PROJECT แต่ละวงอยู่ในการดูแลของบริษัทผู้ผลิตรายการเป็นเวลาสองปี ไม่ใช่บริษัทของคุณ เมมเบอร์ของคุณที่ได้เดบิวต์จะไม่ร่วมกิจกรรมกับวงเดิมจนกว่าสัญญาจะสิ้นสุด แล้วจะกลับมาพร้อมแฟนคลับใหม่จำนวนมาก')}</p></div>
 ${G.map(Z=>{const P=Z.pg;return`<div class="c blpgc"><div class="row"><b>${esc(P.name)}</b><span class="tag">BLOOM ${P.y}</span><span class="tag ${P.ended?'':'tmain'}">${P.ended?BL_T('Contract ended','สัญญาสิ้นสุด')+' '+jd(P.ended):BL_T('Active until','ทำกิจกรรมถึง')+' '+jd(P.until)}</span></div><small>${BL_T('Debut','เดบิวต์')} ${jd(P.from)} · ${BL_T('Contract','สัญญา')} ${jd(P.from)} – ${jd(P.until)} · ${BL_T('Managed by the BLOOM production company','ดูแลโดยบริษัทผู้ผลิตรายการ BLOOM')}</small>
  <div class="blgrid">${P.members.map(x=>{const c=Z.cs.find(c=>c.id==x.cid),m=(x.mid!=null&&(get(x.mid)||(S.alumni||[]).find(a=>a.id==x.mid)))||(c?blObj(c):null);return m?`<div class="c blcard ${x.mid!=null?'mine':''}">${ptc(m,52)}<b>${esc(m.stage||m.name||x.name)}</b><small>${esc(x.pos)}</small><small>${esc(x.co)}${x.grp?' · '+esc(x.grp):''}</small>${x.case?`<small>${BL_T('Return','กลับ')}: ${x.case}</small>`:''}${x.fans?`<small>+${x.fans.toLocaleString()} ${BL_T('fans','แฟน')}</small>`:''}</div>`:''}).join('')}</div></div>`}).join('')||`<div class="c"><p class="st">${BL_T('No Project Group yet.','ยังไม่มีวงโปรเจกต์')}</p></div>`}`};
// member profile: Survival Show History + Episode Gallery
function blHist(m){const B=S&&S.bloom;if(!B)return'';const out=[];Object.values(B.seasons).forEach(Z=>{const c=Z.cs.find(c=>c.mid==m.id||c.mid2==m.id);if(!c)return;const ranks=[3,6,9,12,13].filter(e=>c.rk[e]).map(e=>`EP.${String(e).padStart(2,'0')} #${c.rk[e]}`).join(' · ');const pg=Z.pg&&Z.pg.members.some(x=>x.mid==m.id)?Z.pg:null;
  const mis=[[5,'Group Battle'],[8,'Position Battle'],[11,'Concept Battle'],[13,'Grand Finale']].filter(([e])=>c.sk[e]!=null).map(([e,n])=>`${n} ${c.sk[e]}`).join(' · ');
  const gal=Object.keys(Z.eps).map(Number).sort((a,b)=>a-b).filter(e=>Z.eps[e].st&&Z.eps[e].st[c.id]);
  out.push(`<div class="c blhist"><h3>${BL_T('Survival Show History','ประวัติรายการเซอร์ไววัล')}</h3><div class="row"><b>${Z.name}</b><span class="tag">${c.debut?BL_T('Debuted','เดบิวต์'):c.fin?BL_T('Finalist','ผู้เข้ารอบชิง'):c.out?BL_T('Eliminated','ตกรอบ'):BL_T('Competing','กำลังแข่ง')}</span></div>
  <div class="fbkv">${[[BL_T('EP.01 grade','เกรด EP.01'),blGB(c.g1)||'—'],[BL_T('EP.02 grade','เกรด EP.02'),blGB(c.g2)||'—'],[BL_T('Center eligibility','สิทธิ์เซ็นเตอร์'),c.cand?BL_T('Yes (Grade A)','มี (เกรด A)'):c.g2?BL_T('No','ไม่มี'):'—'],[BL_T('Theme Song Center','เซ็นเตอร์เพลงธีม'),c.center?BL_T('Yes','ใช่'):BL_T('No','ไม่ใช่')],[BL_T('Rankings','อันดับ'),ranks||'—'],[BL_T('Missions','ภารกิจ'),mis||'—'],[BL_T('Eliminated','ตกรอบ'),c.out?`EP.${String(c.out).padStart(2,'0')} (#${c.outRk})`:'—'],[BL_T('Final ranking','อันดับสุดท้าย'),c.fin?'#'+c.fin:'—'],[BL_T('Project Group','วงโปรเจกต์'),pg?`${esc(pg.name)} · ${jd(pg.from)} – ${jd(pg.until)}`:'—']].map(([a,b])=>`<div><small>${a}</small><b>${b}</b></div>`).join('')}</div>
  ${gal.length?`<h4>${BL_T('Episode Gallery','แกลเลอรีแต่ละตอน')}</h4><div class="blgal">${gal.map(e=>`<button onclick="ui.mod=null;blOpenEp(${Z.y},${e})">${blStillSvg(Z,e,c)}</button>`).join('')}</div>`:''}</div>`)});return out.join('')}
{const f=profHtml;profHtml=function(m,cand){let h=f.apply(this,arguments);try{if(!cand&&m&&(ui.ptab||'stats')=='stats'){const x=blHist(m);if(x){const i=h.lastIndexOf('</div>');h=i>0?h.slice(0,i)+x+h.slice(i):h+x}}}catch(e){console.error(e)}return h}}
{const f=migrate;migrate=function(){const r=f.apply(this,arguments);try{if(S&&S.bloom)blS()}catch(e){}return r}}
// BLOOM news has its own pop-up (shown when no other pop-up is open)
{const f=render;render=function(){try{if(S&&ui.blN&&ui.blN.length&&!ui.mod&&!ui.t){ui.mod={t:'html',h:`<h2 class="ht">BLOOM: THE IDOL PROJECT</h2><ul class="ms wln">${ui.blN.join('')}</ul>`};ui.blN=[]}}catch(e){console.error(e)}return f.apply(this,arguments)}}
// ---- the debut group is not the player's: older seasons made it a company group — it becomes the show's group --------------
function blMigratePG(){const B=S&&S.bloom;if(!B||!B.seasons)return 0;let n=0;Object.values(B.seasons).forEach(Z=>{const PG=Z.pg;if(!PG||PG.ext||PG.ended)return;n++;const g=grp(PG.gid);
 const tr=toast,rd=render;toast=()=>{};render=()=>{};try{
  if(g&&S.ag==g.id){const o=S.groups.find(x=>x.id!=g.id&&!(x.proj&&x.type=='project'));if(o)gsSwitch(o.id)}
  PG.members.forEach(x=>{const m=get(x.mid);if(!m)return;const b=m.bproj;x.name=x.name||m.stage||m.name;if(!b)return;
   if(b.npc){const c=Z.cs.find(c=>c.id==x.cid);if(c)delete c.mid2;S.members=S.members.filter(z=>z!==m);x.mid=null;return}
   try{const og=grp(b.og);if(og&&m.group!=og.id){transferGroup(m.id,og.id);const t=(og.teams||[]).find(t=>t.id==b.ot);if(t&&b.ost!='trainee')(typeof joinTeam=='function'?joinTeam(m,t):moveTeam(m.id,t.id))}}catch(e){console.error(e)}
   const b2={...b,ext:1};delete b2.gid;blAway(m,b2)});
  if(g){const used=(gsCtx(g.id,'singles')||[]).length||(g.ctx&&g.ctx.pj)||S.members.some(m=>m.status!='graduated'&&gsGid(m)==g.id);if(!used){S.groups=S.groups.filter(x=>x!==g);PG.gid=null}else{g.ext=1;g.active=false}}
  PG.ext=1;try{if(typeof fdFixAll=='function'){fdFixAll();fdWrite()}}catch(e){}
 }catch(e){console.error(e)}finally{toast=tr;render=rd}});return n}
{const f=migrate;migrate=function(){const r=f.apply(this,arguments);try{const n=blMigratePG();if(n)console.log('BLOOM project groups moved to the show:',n)}catch(e){console.error(e)}return r}}
// a project group kept for its history cannot be managed
{const f=gsSelect;gsSelect=function(gid){const g=grp(+gid);if(g&&g.ext)return toast(BL_T(`${g.name} is managed by the BLOOM production company.`,`${g.name} อยู่ในการดูแลของบริษัทผู้ผลิตรายการ BLOOM`),'err');return f.apply(this,arguments)}}
// busy for the whole project contract (schedules, conflicts)
{const f=blBusyWin;blBusyWin=function(mid){const r=f.apply(this,arguments);if(r)return r;try{const m=get(mid),b=m&&m.bproj;if(b&&b.ext&&S.day<b.until)return[b.from,b.until,{y:b.y,name:b.name}]}catch(e){}return null}}
// elections: she does not stand while she is with the project group
const blPgAway=m=>!!(m&&m.bproj&&m.bproj.ext&&S.day<m.bproj.until);
if(typeof geTog=='function'){const f=geTog;geTog=function(id){if(blPgAway(get(id)))return toast(BL_T('She is with her BLOOM Project Group until the contract ends.','เธออยู่กับวงโปรเจกต์ BLOOM จนกว่าสัญญาจะสิ้นสุด'),'err');return f.apply(this,arguments)}}
if(typeof geAll=='function'){const f=geAll;geAll=function(){const r=f.apply(this,arguments);try{const e=geActive();if(e&&Array.isArray(e.parts))e.parts=e.parts.filter(id=>!blPgAway(get(id)))}catch(x){}return r}}
if(typeof geStartVoting=='function'){const f=geStartVoting;geStartVoting=function(e){try{if(e&&Array.isArray(e.parts))e.parts=e.parts.filter(id=>!blPgAway(get(id)))}catch(x){}return f.apply(this,arguments)}}
